-- F-04: human-readable reference numbers (DSP-2026-000123, FLG-2026-000045).
-- The number is generated by the database from a sequence, so it is unique
-- and safe under concurrent inserts. The year comes from the record's own date.

CREATE SEQUENCE IF NOT EXISTS dispute_reference_seq;
CREATE SEQUENCE IF NOT EXISTS fraud_flag_reference_seq;

ALTER TABLE disputes ADD COLUMN IF NOT EXISTS reference_no VARCHAR(20);
ALTER TABLE fraud_flags ADD COLUMN IF NOT EXISTS reference_no VARCHAR(20);

-- Backfill existing rows oldest-first so numbers follow submission order.
-- row_number() guarantees the order; the sequence is advanced afterwards.
WITH numbered AS (
  SELECT id, submitted_at,
         row_number() OVER (ORDER BY submitted_at, id) AS n
  FROM disputes WHERE reference_no IS NULL
)
UPDATE disputes d
SET reference_no = 'DSP-' || to_char(numbered.submitted_at, 'YYYY') || '-' ||
                   lpad(numbered.n::text, 6, '0')
FROM numbered
WHERE d.id = numbered.id;

WITH numbered AS (
  SELECT id, flagged_at,
         row_number() OVER (ORDER BY flagged_at, id) AS n
  FROM fraud_flags WHERE reference_no IS NULL
)
UPDATE fraud_flags f
SET reference_no = 'FLG-' || to_char(numbered.flagged_at, 'YYYY') || '-' ||
                   lpad(numbered.n::text, 6, '0')
FROM numbered
WHERE f.id = numbered.id;

-- Continue after the highest existing number (safe to re-run).
SELECT setval('dispute_reference_seq',
              GREATEST((SELECT MAX(right(reference_no, 6)::int) FROM disputes), 1),
              (SELECT COUNT(*) FROM disputes) > 0);
SELECT setval('fraud_flag_reference_seq',
              GREATEST((SELECT MAX(right(reference_no, 6)::int) FROM fraud_flags), 1),
              (SELECT COUNT(*) FROM fraud_flags) > 0);

ALTER TABLE disputes
  ALTER COLUMN reference_no SET DEFAULT
    'DSP-' || to_char(now(), 'YYYY') || '-' ||
    lpad(nextval('dispute_reference_seq')::text, 6, '0'),
  ALTER COLUMN reference_no SET NOT NULL;

ALTER TABLE fraud_flags
  ALTER COLUMN reference_no SET DEFAULT
    'FLG-' || to_char(now(), 'YYYY') || '-' ||
    lpad(nextval('fraud_flag_reference_seq')::text, 6, '0'),
  ALTER COLUMN reference_no SET NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_disputes_reference_no
  ON disputes (reference_no);
CREATE UNIQUE INDEX IF NOT EXISTS idx_fraud_flags_reference_no
  ON fraud_flags (reference_no);
